import java.util.*;

class Solution {
    String[] neighboringRecordIds(String[] records, String[] queries) {
        String[] ids = new String[records.length];
        Map<String, Integer> pos = new HashMap<>();
        for (int i = 0; i < records.length; i++) {
            ids[i] = records[i].split("\\|")[0];
            pos.put(ids[i], i);
        }
        String[] res = new String[queries.length];
        int n = ids.length;
        for (int q = 0; q < queries.length; q++) {
            Integer i = pos.get(queries[q]);
            if (i == null) res[q] = "None,None";
            else {
                String pr = i > 0 ? ids[i - 1] : "None";
                String nx = i + 1 < n ? ids[i + 1] : "None";
                res[q] = pr + "," + nx;
            }
        }
        return res;
    }
}

class Solution {
public:
    vector<string> neighboringRecordIds(vector<string>& records, vector<string>& queries) {
        vector<string> ids;
        unordered_map<string, int> pos;
        for (size_t i = 0; i < records.size(); i++) {
            auto sp = records[i].find('|');
            ids.push_back(records[i].substr(0, sp));
            pos[ids.back()] = i;
        }
        vector<string> res;
        int n = ids.size();
        for (auto& q : queries) {
            auto it = pos.find(q);
            if (it == pos.end()) res.push_back("None,None");
            else {
                int i = it->second;
                string pr = i > 0 ? ids[i - 1] : "None";
                string nx = i + 1 < n ? ids[i + 1] : "None";
                res.push_back(pr + "," + nx);
            }
        }
        return res;
    }
};
